<?php
$sections=['posts'=>'Posts','media'=>'Media library','categories'=>'Categories','system'=>'System','tags'=>'Tags','menus'=>'Menus'];
$section=trim(substr(parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH),strlen('/admin')),'/') ?: 'posts';
if(!isset($sections[$section])){http_response_code(404);$section='missing';}
$siteName=setting('site_name','Brainpress');
$statusFilter=in_array($_GET['status']??'', ['published','draft','trash'],true)?$_GET['status']:'';
$adminSearch=mb_substr(trim((string)($_GET['s']??'')),0,200);
$current=max(1,(int)($_GET['page']??1));$perPage=20;
$adminWhere=' WHERE 1=1';$adminParams=[];
if($statusFilter){$adminWhere.=' AND p.status=?';$adminParams[]=$statusFilter;}
if($adminSearch!==''){$adminWhere.=' AND p.title LIKE ?';$adminParams[]='%'.$adminSearch.'%';}
$adminTotal=(int)query('SELECT COUNT(*) FROM posts p'.$adminWhere,$adminParams)->fetchColumn();
$adminPages=max(1,(int)ceil($adminTotal/$perPage));$current=min($current,$adminPages);$adminOffset=($current-1)*$perPage;
$adminPosts=$section==='posts'&&!$editor?query('SELECT p.*,c.name AS category_name FROM posts p JOIN categories c ON c.id=p.category_id'.$adminWhere." ORDER BY p.updated_at DESC,p.id DESC LIMIT $perPage OFFSET $adminOffset",$adminParams)->fetchAll():[];
function menuRow(array $item,int $index): void { ?>
<div class="menu-item"><label class="menu-visible"><input type="checkbox" name="enabled[]" value="<?=$index?>" <?=($item['visible']??true)?'checked':''?>> Show</label><input name="label[]" aria-label="Menu label <?=$index+1?>" maxlength="40" placeholder="Label" value="<?=e($item['label']??'')?>"><input name="url[]" aria-label="Menu URL <?=$index+1?>" placeholder="/ or https://…" value="<?=e($item['url']??'')?>"><div class="menu-order"><button type="button" class="text-button" data-up aria-label="Move up">↑</button><button type="button" class="text-button" data-down aria-label="Move down">↓</button><button type="button" class="text-button" data-remove>Remove</button></div></div>
<?php }
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf" content="<?=e($_SESSION['csrf'])?>"><meta name="theme-color" content="#ffffff"><title><?=e($sections[$section]??'Not found')?> · <?=e($siteName)?> Admin</title><script src="/assets/theme.js"></script><link rel="stylesheet" href="/assets/app.css?v=6"><link rel="stylesheet" href="/assets/admin.css?v=2"><link rel="stylesheet" href="/assets/vendor/katex.min.css"><script src="/assets/app.js?v=5" defer></script><script src="/assets/admin.js?v=1" defer></script><script type="module" src="/assets/vendor/render.js"></script></head>
