<div class="admin-shell"><aside class="admin-sidebar"><p>PUBLISHING</p><nav aria-label="Administration"><?php foreach($sections as $key=>$label):?><a href="/admin/<?=$key?>" class="<?=$section===$key?'active':''?>" <?=$section===$key?'aria-current="page"':''?>><?=icon(['posts'=>'edit','media'=>'image','categories'=>'grid','system'=>'sun','tags'=>'share','menus'=>'menu'][$key])?><?=e($label)?></a><?php endforeach;?></nav><div class="admin-side-note">Your Markdown publishing space.</div></aside>
<main class="admin-main"><div class="admin-page-heading"><div><p class="muted">YOUR WORKSPACE</p><h1><?=e($sections[$section]??'Page not found')?></h1></div><?php if($section==='posts'):?><a class="button" href="/admin/posts?write">New post</a><?php endif;?></div><p id="admin-message" role="status" class="admin-message"></p>
<?php if($section==='missing'):?><section class="panel admin-panel"><p>This admin page does not exist.</p><a href="/admin">Back to posts</a></section>
<?php elseif($section==='posts'&&$missing):?><section class="panel admin-panel">Post not found.</section>
<?php elseif($section==='posts'&&$editor):?><?php writeForm($categories,$post,$categoryId);?>
<?php elseif($section==='posts'):?>
<section class="panel admin-panel"><form class="admin-filters" action="/admin/posts"><label class="sr-only" for="post-search">Search posts</label><input id="post-search" name="s" placeholder="Search titles" value="<?=e($adminSearch)?>"><label class="sr-only" for="status-filter">Publication status</label><select name="status" id="status-filter"><option value="">All statuses</option><?php foreach(['published','draft','trash'] as $state):?><option value="<?=$state?>" <?=$state===$statusFilter?'selected':''?>><?=ucfirst($state)?></option><?php endforeach;?></select><button class="button">Filter</button></form>
<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Title</th><th>Category</th><th>Status</th><th>Updated</th><th>Actions</th></tr></thead><tbody><?php foreach($adminPosts as $item):?><tr><td><strong><?=e($item['title'])?></strong></td><td><?=e($item['category_name'])?></td><td><span class="status-badge <?=$item['status']?>"><?=e(ucfirst($item['status']))?></span></td><td class="muted"><?=e(substr($item['updated_at'],0,16))?></td><td><div class="admin-row-actions"><?php if($item['status']==='trash'):?><button class="text-button" data-post-action="restore" data-id="<?=$item['id']?>">Restore</button><?php else:?><a href="/admin/posts?edit=<?=$item['id']?>">Edit</a><?php if($item['status']==='published'):?><a href="/?post=<?=$item['id']?>">View</a><?php endif;?><button class="text-button" data-post-action="trash" data-id="<?=$item['id']?>">Trash</button><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div><?php if(!$adminPosts):?><div class="admin-empty">No posts match this view.</div><?php endif;?>
<nav class="pagination" aria-label="Posts pages"><span><?=$adminTotal?> posts · <?=$current?> / <?=$adminPages?></span><?php foreach([-1=>'Previous',1=>'Next'] as $step=>$label):if($current+$step<1||$current+$step>$adminPages)continue;?><a href="/admin/posts?<?=e(http_build_query(['s'=>$adminSearch,'status'=>$statusFilter,'page'=>$current+$step]))?>"><?=$label?></a><?php endforeach;?></nav></section>
<?php elseif($section==='categories'):?>
<section class="panel admin-panel"><div class="admin-section-heading"><h2>Organize your posts</h2><button class="button" data-add-category>New category</button></div><p class="muted">Deleting a category transfers all of its posts, including drafts and trash.</p>
<?php foreach($categories as $c):?><div class="taxonomy-row"><form data-admin-action="category_rename"><input type="hidden" name="id" value="<?=$c['id']?>"><label class="sr-only" for="category-<?=$c['id']?>">Category name</label><input id="category-<?=$c['id']?>" name="name" maxlength="40" value="<?=e($c['name'])?>" required><span class="muted"><?=$c['total']?> published</span><button type="submit" class="text-button">Rename</button></form><form data-admin-action="category_delete"><input type="hidden" name="id" value="<?=$c['id']?>"><label class="sr-only" for="target-<?=$c['id']?>">Transfer posts to</label><select name="target" id="target-<?=$c['id']?>"><option value="">Transfer posts to…</option><?php foreach($categories as $other):if($other['id']===$c['id'])continue;?><option value="<?=$other['id']?>"><?=e($other['name'])?></option><?php endforeach;?></select><button type="submit" class="text-button">Delete category</button></form></div><?php endforeach;?><?php if(!$categories):?><div class="admin-empty">Create your first category to start publishing.</div><?php endif;?></section>
<?php elseif($section==='tags'): $tags=query('SELECT t.*,COUNT(pt.post_id) AS total FROM tags t LEFT JOIN post_tags pt ON pt.tag_id=t.id GROUP BY t.id,t.name ORDER BY t.name')->fetchAll();?>
<section class="panel admin-panel"><h2>Post tags</h2><p class="muted">Use comma-separated tags in the editor. Removing a tag keeps its posts.</p><form data-admin-action="tag_create" class="admin-inline-form"><label class="sr-only" for="new-tag">New tag</label><input id="new-tag" name="name" placeholder="New tag" maxlength="40" required><button class="button" type="submit">Add tag</button></form>
<?php foreach($tags as $tag):?><form class="taxonomy-row tag-row" data-admin-action="tag_rename"><input type="hidden" name="id" value="<?=$tag['id']?>"><label class="sr-only" for="tag-<?=$tag['id']?>">Tag name</label><input id="tag-<?=$tag['id']?>" name="name" maxlength="40" value="<?=e($tag['name'])?>" required><span class="muted"><?=$tag['total']?> posts</span><button class="text-button" type="submit">Rename</button><button class="text-button" type="submit" data-action="tag_delete" formnovalidate>Delete tag</button></form><?php endforeach;?><?php if(!$tags):?><div class="admin-empty">No tags yet.</div><?php endif;?></section>
<?php elseif($section==='media'): $mediaTrash=isset($_GET['trash']); $media=mediaLibrary($mediaTrash?'trash':'active');?>
