<div class="media-grid"><?php foreach($media as $image):$url='/uploads/'.$image['filename'];$snippet='!['.str_replace(['[',']',"\n","\r"],['\\[','\\]',' ',' '],$image['alt']).']('.$url.')';?><article class="panel media-card"><a href="<?=e($url)?>" target="_blank" rel="noopener"><img src="<?=e($url)?>" alt="<?=e($image['alt'])?>" loading="lazy"></a><form data-admin-action="media_update"><input type="hidden" name="id" value="<?=$image['id']?>"><label>Title<input name="title" value="<?=e($image['title'])?>" maxlength="200"></label><label>Alternative text<input name="alt" value="<?=e($image['alt'])?>" maxlength="500"></label><label>Markdown<input class="media-markdown" readonly value="<?=e($snippet)?>"></label><div class="admin-row-actions"><button class="text-button" type="submit">Save details</button><button class="text-button" type="button" data-copy-media="<?=e($snippet)?>">Copy Markdown</button><button class="text-button" type="submit" formnovalidate data-action="<?=$mediaTrash?'media_restore':'media_trash'?>"><?=$mediaTrash?'Restore':'Trash'?></button></div></form></article><?php endforeach;?></div><?php if(!$media):?><div class="panel admin-empty"><?=$mediaTrash?'No trashed images.':'Upload an image to start your library.'?></div><?php endif;?>
<?php elseif($section==='menus'):?>
