<?php elseif($section==='system'):?>
<section class="panel admin-panel"><h2>Site settings</h2><form class="settings-form" data-admin-action="settings_save" data-stay><label>Site name<input name="site_name" value="<?=e($siteName)?>" maxlength="60" required></label><label>Logo URL<input name="logo_url" value="<?=e(setting('logo_url','/assets/site-logo.svg'))?>" placeholder="/assets/site-logo.svg" maxlength="1000"></label><label>Description<textarea name="description" maxlength="200" rows="3"><?=e(setting('description','Powered by Markdown.'))?></textarea></label><button class="button" type="submit">Save settings</button><p role="status"></p></form></section>
<section class="panel admin-panel"><h2>Environment</h2><dl class="environment-list"><dt>PHP</dt><dd><?=e(PHP_VERSION)?></dd><dt>Database</dt><dd><?=e(db()->getAttribute(PDO::ATTR_DRIVER_NAME))?></dd><dt>Storage writable</dt><dd><?=is_writable(dirname(__DIR__).'/storage')?'Yes':'No'?></dd><dt>Uploads writable</dt><dd><?=is_writable(dirname(__DIR__).'/public/uploads')?'Yes':'No'?></dd></dl><p class="muted">Personal testing mode: there is no login. Protect a cloud test site through your server settings.</p></section>
